                0 <= idx <= num_replicas,
                min_local_version <= MAX_IDX,
                g_cb_comb_new.instance_id() == self.cyclic_buffer_instance@.id(),
                g_cb_comb_new.value().is_AdvancingHead(),
                g_cb_comb_new.value().get_AdvancingHead_idx() == idx,
